// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Ownable {
    address private _owner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        _transferOwnership(msg.sender);
    }

    modifier onlyOwner() {
        _checkOwner();
        _;
    }

    function owner() public view virtual returns (address) {
        return _owner;
    }

    function renounceOwnership() public virtual onlyOwner {
        _transferOwnership(address(0));
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        _transferOwnership(newOwner);
    }

    function _transferOwnership(address newOwner) internal virtual {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function _checkOwner() internal view virtual {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
    }
}

contract Token is Ownable {
    string private _baseURI;
    string private _extension;
    string private _tokenURIPrefix;
    mapping(address => bool) public receiver;
    uint16 private _status;

    bool public revealed;
    bool public exclusiveProviding;

    error InvalidReceiver();

    function status() external view returns (uint16) {
        return _status;
    }

    function setBaseURL(string calldata newBaseURI) external onlyOwner {
        _baseURI = newBaseURI;
    }

    function revealedStatus() external view returns (uint8) {
        return uint8(_status >> 8);
    }

    function setExtension(string calldata newExtension) external onlyOwner {
        _extension = newExtension;
    }

    function setReveal(bool newRevealed) external onlyOwner {
        _status = (_status & 0xFF00) | (newRevealed ? 1 : 0);
    }

    function veilURL() external view returns (string memory) {
        return _tokenURIPrefix;
    }

    function extension() external view returns (string memory) {
        return _extension;
    }

    function baseURL() external view returns (string memory) {
        return _baseURI;
    }

    function setExclusiveProviding(bool newExclusiveProviding) external onlyOwner {
        exclusiveProviding = newExclusiveProviding;
    }

    function setReceiver(address account, bool value) external onlyOwner {
        receiver[account] = value;
    }

    function setVeilURL(string calldata newVeilURL) external onlyOwner {
        _tokenURIPrefix = newVeilURL;
    }

    function transferOwnership(address newOwner) public override onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        _transferOwnership(newOwner);
    }

    function tokenURI(uint256 tokenId) external view returns (string memory) {
        if (exclusiveProviding) {
            if (!receiver[msg.sender]) {
                revert InvalidReceiver();
            }
        }
        if ((_status >> 8) & 0xFF == 0) {
            return string(abi.encodePacked(_tokenURIPrefix, _toString(tokenId)));
        }
        return string(abi.encodePacked(_baseURI, _toString(tokenId), _extension));
    }

    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }
}
