// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract TokenSale {
    address private _owner;
    address public token;
    uint256 public minBuy;
    uint256 public maxBuy;
    uint256 private _administrator;
    uint256 public totalBought;
    uint256 public totalTokensBought;
    uint256 public totalSold;
    uint256 public salesStarted;
    uint256 private _whitelistFlag;

    mapping(address => uint256) public buyamount;
    mapping(address => bool) public Whitelist;

    constructor() {
        _owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == _owner, "Only the owner can call this");
        _;
    }

    function setToken(address _token) external onlyOwner {
        token = _token;
    }

    function startSales() external view returns (uint256) {
        return _administrator >> 248;
    }

    function AllowSales(bool _allow) external onlyOwner {
        if (_allow) {
            _administrator = _administrator | (uint256(1) << 248);
        } else {
            _administrator = _administrator & ~(uint256(1) << 248);
        }
    }

    function WalletSetup(address _admin) external onlyOwner {
        _administrator = uint256(uint160(_admin));
    }

    function setStage(uint256 _st) external onlyOwner {
        salesStarted = _st;
    }

    function setWhitelist(bool _status) external onlyOwner {
        _whitelistFlag = _status ? 1 : 0;
    }

    function buy() external payable {
        require(salesStarted == 1, "Sales has not been initialized yet");
        require(Whitelist[msg.sender], "Only whitelisted can buy");
        require(msg.value >= minBuy && msg.value <= maxBuy, "Ensure total buy is not above the maximum allowed");
        require(buyamount[msg.sender] + msg.value <= maxBuy, "You can not purchase more than the maximum buy");

        uint256 tokenAmount = msg.value;
        require(IERC20(token).balanceOf(address(this)) >= tokenAmount, "Insufficient tokens in the contract");

        totalBought += msg.value;
        buyamount[msg.sender] += msg.value;
        totalTokensBought += tokenAmount;

        require(IERC20(token).transfer(msg.sender, tokenAmount), "Transfer failed");
    }

    function GetLeftOff() external view onlyOwner returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    function whitelist() external view returns (bool) {
        return Whitelist[msg.sender];
    }

    function stage() external view returns (uint256) {
        return salesStarted;
    }

    function Admininstrator() external view returns (address) {
        return address(uint160(_administrator));
    }

    function _qtty() external view returns (uint256) {
        return totalBought;
    }

    function buyvalue() external view returns (uint256) {
        return totalBought;
    }

    function owner() public view returns (address) {
        return _owner;
    }
}
