// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract ONFT {
    // ERC721 storage
    string private _name;
    string private _symbol;
    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    // Ownable storage
    address private _owner;

    // LayerZero storage
    address public lzEndpoint;
    mapping(uint16 => bytes) public trustedRemoteLookup;
    mapping(uint16 => mapping(uint16 => uint256)) public minDstGasLookup;
    mapping(uint16 => uint256) public payloadSizeLimitLookup;
    mapping(uint16 => mapping(bytes => mapping(uint64 => bytes))) public failedMessages;
    uint16 public constant DEFAULT_PAYLOAD_SIZE_LIMIT = 10000;

    // Minting storage
    uint256 public constant MAX_SUPPLY = 10000;
    uint256 public constant MAX_AMOUNT = 5;
    uint256 public totalSupply;
    uint256 public price;
    uint256 private _mintCounter;
    string private _baseURI;

    // Packed storage for mintActive and precrime
    // slot 0x0e: lower byte = mintActive flag, upper 20 bytes = precrime address
    uint256 private _mintActiveAndPrecrime;

    // Events
    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event MessageFailed(uint16 srcChainId, bytes srcAddress, uint64 nonce, bytes payload, bytes reason);
    event RetryMessageSuccess(uint16 srcChainId, bytes srcAddress, uint64 nonce, bytes32 payloadHash);
    event SetTrustedRemote(uint16 chainId, bytes path);
    event SetTrustedRemoteAddress(uint16 chainId, bytes path);
    event SetMinDstGas(uint16 dstChainId, uint16 packetType, uint256 minGas);
    event SetPrecrime(address precrime);

    // Errors
    error MintNotActive();
    error NoContracts();
    error TooManyMints();
    error IncorrectFunds();
    error NotEnoughSupply();
    error NotTokenOwner();
    error ETHTransferFailed();
    error InvalidMinGas();
    error LzAppInvalidEndpointCaller();
    error LzAppInvalidSourceSendingContract();
    error LzAppNoTrustedPathRecord();
    error NonblockingLzAppNoStoredMessage();
    error NonblockingLzAppInvalidPayload();
    error LzAppDestinationChainNotTrustedSource();
    error OwnableCallerNotOwner();
    error OwnableNewOwnerIsZeroAddress();
    error ZeroAddress();
    error WrongFrom();
    error NonblockingLzAppCallerMustBeThisContract();
    error SliceOverflow();
    error SliceOutOfBounds();
    error PayloadSizeTooLarge();

    modifier onlyOwner() {
        if (_owner != msg.sender) revert OwnableCallerNotOwner();
        _;
    }

    modifier thisContractOnly() {
        if (msg.sender != address(this)) revert NonblockingLzAppCallerMustBeThisContract();
        _;
    }

    constructor(string memory name_, string memory symbol_, address lzEndpoint_) {
        _name = name_;
        _symbol = symbol_;
        _owner = msg.sender;
        lzEndpoint = lzEndpoint_;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    // ERC721 functions
    function name() public view returns (string memory) {
        return _name;
    }

    function symbol() public view returns (string memory) {
        return _symbol;
    }

    function balanceOf(address owner_) public view returns (uint256) {
        if (owner_ == address(0)) revert ZeroAddress();
        return _balances[owner_];
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner_ = _owners[tokenId];
        if (owner_ == address(0)) revert NotTokenOwner();
        return owner_;
    }

    function tokenURI(uint256 tokenId) public view returns (string memory) {
        if (_owners[tokenId] == address(0)) revert NotTokenOwner();
        return string(abi.encodePacked(_baseURI, _toString(tokenId)));
    }

    function baseURI() public view returns (string memory) {
        return _baseURI;
    }

    function approve(address to, uint256 tokenId) public {
        address owner_ = ownerOf(tokenId);
        if (to == owner_) revert WrongFrom();
        if (msg.sender != owner_ && !isApprovedForAll(owner_, msg.sender)) revert WrongFrom();
        _tokenApprovals[tokenId] = to;
        emit Approval(owner_, to, tokenId);
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        if (_owners[tokenId] == address(0)) revert NotTokenOwner();
        return _tokenApprovals[tokenId];
    }

    function setApprovalForAll(address operator, bool approved) public {
        if (operator == msg.sender) revert WrongFrom();
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address owner_, address operator) public view returns (bool) {
        return _operatorApprovals[owner_][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert WrongFrom();
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) public {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert WrongFrom();
        _safeTransfer(from, to, tokenId, data);
    }

    function _isApprovedOrOwner(address spender, uint256 tokenId) internal view returns (bool) {
        address owner_ = ownerOf(tokenId);
        return (spender == owner_ || _tokenApprovals[tokenId] == spender || isApprovedForAll(owner_, spender));
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        if (ownerOf(tokenId) != from) revert WrongFrom();
        if (to == address(0)) revert ZeroAddress();

        delete _tokenApprovals[tokenId];

        _balances[from] -= 1;
        _balances[to] += 1;
        _owners[tokenId] = to;

        emit Transfer(from, to, tokenId);
    }

    function _safeTransfer(address from, address to, uint256 tokenId, bytes memory data) internal {
        _transfer(from, to, tokenId);
        if (!_checkOnERC721Received(from, to, tokenId, data)) revert WrongFrom();
    }

    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data) internal returns (bool) {
        if (to.code.length == 0) return true;

        try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
            return retval == IERC721Receiver.onERC721Received.selector;
        } catch {
            return false;
        }
    }

    function _mint(address to, uint256 tokenId) internal {
        if (to == address(0)) revert ZeroAddress();
        if (_owners[tokenId] != address(0)) revert WrongFrom();

        _balances[to] += 1;
        _owners[tokenId] = to;

        emit Transfer(address(0), to, tokenId);
    }

    function _burn(uint256 tokenId) internal {
        address owner_ = ownerOf(tokenId);

        delete _tokenApprovals[tokenId];

        _balances[owner_] -= 1;
        delete _owners[tokenId];

        emit Transfer(owner_, address(0), tokenId);
    }

    // ERC165
    function supportsInterface(bytes4 interfaceId) public pure returns (bool) {
        return interfaceId == type(IERC721).interfaceId ||
               interfaceId == type(IERC721Metadata).interfaceId ||
               interfaceId == type(IERC165).interfaceId;
    }

    // Ownable functions
    function owner() public view returns (address) {
        return _owner;
    }

    function transferOwnership(address newOwner) public onlyOwner {
        if (newOwner == address(0)) revert OwnableNewOwnerIsZeroAddress();
        _transferOwnership(newOwner);
    }

    function _transferOwnership(address newOwner) internal {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function renounceOwnership() public onlyOwner {
        _transferOwnership(address(0));
    }

    // Minting functions
    function mintActive() public view returns (bool) {
        return (_mintActiveAndPrecrime & 0xff) != 0;
    }

    function precrime() public view returns (address) {
        return address(uint160(_mintActiveAndPrecrime >> 8));
    }

    function flipMint() public onlyOwner {
        _mintActiveAndPrecrime = (_mintActiveAndPrecrime & ~uint256(0xff)) | (mintActive() ? 0 : 1);
    }

    function setPrice(uint256 price_) public onlyOwner {
        price = price_;
    }

    function setBaseURI(string memory baseURI_) public onlyOwner {
        _baseURI = baseURI_;
    }

    function mint(uint256 amount) public payable {
        if (!mintActive()) revert MintNotActive();
        if (tx.origin != msg.sender) revert NoContracts();
        if (amount > MAX_AMOUNT) revert TooManyMints();
        if (msg.value != price * amount) revert IncorrectFunds();
        if (totalSupply + amount > MAX_SUPPLY) revert NotEnoughSupply();

        for (uint256 i = 0; i < amount; i++) {
            _mint(msg.sender, ++_mintCounter);
        }
        totalSupply += amount;
    }

    function withdraw() public onlyOwner {
        (bool success, ) = payable(_owner).call{value: address(this).balance}("");
        if (!success) revert ETHTransferFailed();
    }

    // LayerZero functions
    function setTrustedRemote(uint16 chainId, bytes memory path) public onlyOwner {
        trustedRemoteLookup[chainId] = path;
        emit SetTrustedRemote(chainId, path);
    }

    function setTrustedRemoteAddress(uint16 chainId, bytes memory path) public onlyOwner {
        trustedRemoteLookup[chainId] = abi.encodePacked(path, address(this));
        emit SetTrustedRemoteAddress(chainId, path);
    }

    function getTrustedRemoteAddress(uint16 chainId) public view returns (bytes memory) {
        bytes memory path = trustedRemoteLookup[chainId];
        return path.length >= 20 ? bytes(path[:20]) : "";
    }

    function isTrustedRemote(uint16 chainId, bytes memory srcAddress) public view returns (bool) {
        bytes memory trusted = trustedRemoteLookup[chainId];
        if (trusted.length == 0) return false;
        return keccak256(trusted) == keccak256(srcAddress);
    }

    function setMinDstGas(uint16 dstChainId, uint16 packetType, uint256 minGas) public onlyOwner {
        if (minGas == 0) revert InvalidMinGas();
        minDstGasLookup[dstChainId][packetType] = minGas;
        emit SetMinDstGas(dstChainId, packetType, minGas);
    }

    function setPayloadSizeLimit(uint16 chainId, uint256 limit) public onlyOwner {
        payloadSizeLimitLookup[chainId] = limit;
    }

    function setPrecrime(address precrime_) public onlyOwner {
        _mintActiveAndPrecrime = (_mintActiveAndPrecrime & uint256(0xff)) | (uint256(uint160(precrime_)) << 8);
        emit SetPrecrime(precrime_);
    }

    function setSendVersion(uint16 version) public onlyOwner {
        ILayerZeroEndpoint(lzEndpoint).setSendVersion(version);
    }

    function setReceiveVersion(uint16 version) public onlyOwner {
        ILayerZeroEndpoint(lzEndpoint).setReceiveVersion(version);
    }

    function forceResumeReceive(uint16 srcChainId, bytes memory srcAddress) public onlyOwner {
        ILayerZeroEndpoint(lzEndpoint).forceResumeReceive(srcChainId, srcAddress);
    }

    function setConfig(uint16 version, uint16 chainId, uint256 configType, bytes memory config) public onlyOwner {
        ILayerZeroEndpoint(lzEndpoint).setConfig(version, chainId, configType, config);
    }

    function getConfig(uint16 version, uint16 chainId, address addr, uint256 configType) public view returns (bytes memory) {
        return ILayerZeroEndpoint(lzEndpoint).getConfig(version, chainId, addr, configType);
    }

    function send(uint16 dstChainId, bytes memory destination, bytes memory payload, address payable refundAddress, address zroPaymentAddress, bytes memory adapterParams) public payable {
        _checkAdapterParams(dstChainId, 1, adapterParams);

        bytes memory trustedRemote = trustedRemoteLookup[dstChainId];
        if (trustedRemote.length == 0) revert LzAppNoTrustedPathRecord();

        ILayerZeroEndpoint(lzEndpoint).send{value: msg.value}(
            dstChainId,
            trustedRemote,
            payload,
            refundAddress,
            zroPaymentAddress,
            adapterParams
        );
    }

    function traverseChains(uint16 dstChainId, uint256 tokenId) public payable {
        if (ownerOf(tokenId) != msg.sender) revert NotTokenOwner();

        _burn(tokenId);
        totalSupply--;

        bytes memory payload = abi.encode(msg.sender, tokenId);

        bytes memory adapterParams = _defaultAdapterParams();

        send(dstChainId, abi.encodePacked(address(this)), payload, payable(msg.sender), address(0), adapterParams);
    }

    function lzReceive(uint16 srcChainId, bytes memory srcAddress, uint64 nonce, bytes memory payload) public {
        if (msg.sender != lzEndpoint) revert LzAppInvalidEndpointCaller();

        bytes memory trusted = trustedRemoteLookup[srcChainId];
        if (trusted.length == 0 || keccak256(trusted) != keccak256(srcAddress)) {
            revert LzAppInvalidSourceSendingContract();
        }

        _blockingLzReceive(srcChainId, srcAddress, nonce, payload);
    }

    function _blockingLzReceive(uint16 srcChainId, bytes memory srcAddress, uint64 nonce, bytes memory payload) internal {
        (bool success, bytes memory reason) = address(this).call(abi.encodeWithSelector(this.nonblockingLzReceive.selector, srcChainId, srcAddress, nonce, payload));

        if (!success) {
            _storeFailedMessage(srcChainId, srcAddress, nonce, payload, reason);
            emit MessageFailed(srcChainId, srcAddress, nonce, payload, reason);
        }
    }

    function _storeFailedMessage(uint16 srcChainId, bytes memory srcAddress, uint64 nonce, bytes memory payload, bytes memory reason) internal {
        failedMessages[srcChainId][srcAddress][nonce] = keccak256(payload);
    }

    function nonblockingLzReceive(uint16 srcChainId, bytes memory srcAddress, uint64 nonce, bytes memory payload) public thisContractOnly {
        bytes memory trusted = trustedRemoteLookup[srcChainId];
        if (trusted.length == 0) revert LzAppNoTrustedPathRecord();
        if (keccak256(trusted) != keccak256(srcAddress)) revert LzAppInvalidSourceSendingContract();

        if (failedMessages[srcChainId][srcAddress][nonce].length != 0) {
            delete failedMessages[srcChainId][srcAddress][nonce];
        }

        _nonblockingLzReceive(srcChainId, srcAddress, nonce, payload);
    }

    function _nonblockingLzReceive(uint16 srcChainId, bytes memory srcAddress, uint64 nonce, bytes memory payload) internal {
        (address to, uint256 tokenId) = abi.decode(payload, (address, uint256));

        _mint(to, tokenId);
        totalSupply++;
    }

    function retryMessage(uint16 srcChainId, bytes memory srcAddress, uint64 nonce, bytes memory payload) public {
        bytes32 payloadHash = failedMessages[srcChainId][srcAddress][nonce];
        if (payloadHash == bytes32(0)) revert NonblockingLzAppNoStoredMessage();
        if (keccak256(payload) != payloadHash) revert NonblockingLzAppInvalidPayload();

        delete failedMessages[srcChainId][srcAddress][nonce];

        _nonblockingLzReceive(srcChainId, srcAddress, nonce, payload);

        emit RetryMessageSuccess(srcChainId, srcAddress, nonce, payloadHash);
    }

    function _checkAdapterParams(uint16 dstChainId, uint16 pkType, bytes memory adapterParams) internal view {
        if (adapterParams.length == 0) {
            if (minDstGasLookup[dstChainId][pkType] > 0) revert InvalidMinGas();
            return;
        }

        uint256 minGas = minDstGasLookup[dstChainId][pkType];
        if (minGas == 0) revert InvalidMinGas();

        uint256 gasAmount = uint256(bytes32(adapterParams));
        if (gasAmount < minGas) revert InvalidMinGas();

        uint256 sizeLimit = payloadSizeLimitLookup[dstChainId];
        if (sizeLimit == 0) sizeLimit = DEFAULT_PAYLOAD_SIZE_LIMIT;

        if (adapterParams.length > sizeLimit) revert PayloadSizeTooLarge();
    }

    function _defaultAdapterParams() internal pure returns (bytes memory) {
        return abi.encodePacked(uint16(1), uint256(200000));
    }

    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) return "0";

        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }

        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + (value % 10)));
            value /= 10;
        }

        return string(buffer);
    }

