    uint256 private _tFeeTotal;

    mapping(address => uint256) private _rOwned;
    mapping(address => uint256) private _tOwned;
    mapping(address => mapping(address => uint256)) private _allowances;

    mapping(address => bool) private _isExcludedFromFee;
    mapping(address => bool) private _isExcludedFromReward;
    mapping(address => bool) private _isExcludedFromMaxWallet;
    mapping(address => bool) private _isExcludedFromMaxTx;
    mapping(address => bool) private automatedMarketMakerPairs;

    address[] private _excluded;

    uint256 public _taxFeeBuy;
    uint256 public _liquidityFeeBuy;
    uint256 public _marketingFeeBuy;
    uint256 public _burnFeeBuy;

    uint256 public _taxFeeSell;
    uint256 public _liquidityFeeSell;
    uint256 public _marketingFeeSell;
    uint256 public _burnFeeSell;

    uint256 public _taxFeeTransfer;
    uint256 public _liquidityFeeTransfer;
    uint256 public _marketingFeeTransfer;
    uint256 public _burnFeeTransfer;

    uint256 public maxTxAmount;
    uint256 public maxWalletSize;
    uint256 public minLpTokens;

    address public marketingWallet;
    address public uniswapPair;
    IUniswapV2Router02 public uniswapV2Router;

    bool private inSwapAndLiquify;
    bool public swapAndLiquifyEnabled;
    bool public tradingPaused;

    uint256 private _previousTaxFee;
    uint256 private _previousLiquidityFee;
    uint256 private _previousMarketingFee;
    uint256 private _previousBurnFee;

    uint256 private _feeDenominator = 100;
    uint256 private deadBlocks;
    uint256 private launchBlock;

    event SwapAndLiquify(uint256 tokensSwapped, uint256 ethReceived, uint256 tokensIntoLiquidity);
    event SwapAndLiquifyEnabledUpdated(bool enabled);

    modifier lockTheSwap() {
        inSwapAndLiquify = true;
        _;
        inSwapAndLiquify = false;
    }

    constructor() {
        _name = "Token";
        _symbol = "TKN";
        _decimals = 18;

        uint256 tSupply = 1000000 * 10**_decimals;
        _tTotal = tSupply;
        _rTotal = (type(uint256).max - (type(uint256).max % _tTotal));

        _rOwned[msg.sender] = _rTotal;

        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
        uniswapV2Router = _uniswapV2Router;
        uniswapPair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());

        _isExcludedFromFee[owner()] = true;
        _isExcludedFromFee[address(this)] = true;
        _isExcludedFromFee[marketingWallet] = true;

        _isExcludedFromMaxWallet[owner()] = true;
        _isExcludedFromMaxWallet[address(this)] = true;
        _isExcludedFromMaxWallet[uniswapPair] = true;

        _isExcludedFromMaxTx[owner()] = true;
        _isExcludedFromMaxTx[address(this)] = true;

        automatedMarketMakerPairs[uniswapPair] = true;

        maxTxAmount = _tTotal / 100;
        maxWalletSize = _tTotal / 50;
        minLpTokens = _tTotal / 1000;

        emit Transfer(address(0), msg.sender, _tTotal);
    }

    function name() external view returns (string memory) {
        return _name;
    }

    function symbol() external view returns (string memory) {
        return _symbol;
    }

    function decimals() external view returns (uint8) {
        return _decimals;
    }

    function totalSupply() external view override returns (uint256) {
        return _tTotal;
    }

    function balanceOf(address account) public view override returns (uint256) {
        if (_isExcludedFromReward[account]) return _tOwned[account];
        return tokenFromReflection(_rOwned[account]);
    }

    function transfer(address recipient, uint256 amount) external override returns (bool) {
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    function allowance(address owner_, address spender) external view override returns (uint256) {
        return _allowances[owner_][spender];
    }

    function approve(address spender, uint256 amount) external override returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external override returns (bool) {
        _transfer(sender, recipient, amount);
        uint256 currentAllowance = _allowances[sender][msg.sender];
        require(currentAllowance >= amount, "ERC20: transfer amount exceeds allowance");
        _approve(sender, msg.sender, currentAllowance - amount);
        return true;
    }

    function increaseAllowance(address spender, uint256 addedValue) external returns (bool) {
        _approve(msg.sender, spender, _allowances[msg.sender][spender] + addedValue);
        return true;
    }

    function decreaseAllowance(address spender, uint256 subtractedValue) external returns (bool) {
        uint256 currentAllowance = _allowances[msg.sender][spender];
        require(currentAllowance >= subtractedValue, "ERC20: decreased allowance below zero");
        _approve(msg.sender, spender, currentAllowance - subtractedValue);
        return true;
    }

    function tokenFromReflection(uint256 rAmount) public view returns (uint256) {
        require(rAmount <= _rTotal, "Amount must be less than total reflections");
        uint256 currentRate = _getRate();
        return rAmount / currentRate;
    }

    function reflectionFromToken(uint256 tAmount, bool deductTransferFee) external view returns (uint256) {
        require(tAmount <= _tTotal, "Amount must be less than supply");
        uint256 currentRate = _getRate();
        if (!deductTransferFee) {
            return tAmount * currentRate;
        }
        uint256 tFee = tAmount * _taxFeeBuy / _feeDenominator;
        uint256 tLiquidity = tAmount * _liquidityFeeBuy / _feeDenominator;
        uint256 tMarketing = tAmount * _marketingFeeBuy / _feeDenominator;
        uint256 tBurn = tAmount * _burnFeeBuy / _feeDenominator;
        uint256 tTransferAmount = tAmount - tFee - tLiquidity - tMarketing - tBurn;
        return tTransferAmount * currentRate;
    }

    function _getRate() private view returns (uint256) {
        uint256 rSupply = _rTotal;
        uint256 tSupply = _tTotal;
        for (uint256 i = 0; i < _excluded.length; i++) {
            if (_rOwned[_excluded[i]] > rSupply || _tOwned[_excluded[i]] > tSupply) return _rTotal / _tTotal;
            rSupply -= _rOwned[_excluded[i]];
            tSupply -= _tOwned[_excluded[i]];
        }
        if (tSupply == 0 || rSupply < tSupply) return _rTotal / _tTotal;
        return rSupply / tSupply;
    }

    function _approve(address owner_, address spender, uint256 amount) private {
        require(owner_ != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");
        _allowances[owner_][spender] = amount;
        emit Approval(owner_, spender, amount);
    }

    function _transfer(address from, address to, uint256 amount) private {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");
        require(amount > 0, "Transfer amount must be greater than zero");

        if (from != owner() && to != owner()) {
            if (!tradingPaused) {
                require(automatedMarketMakerPairs[from] || automatedMarketMakerPairs[to], "Trading not enabled");
            }

            if (!_isExcludedFromMaxTx[from] && !_isExcludedFromMaxTx[to]) {
                require(amount <= maxTxAmount, "Transfer amount exceeds max tx");
            }

            if (!_isExcludedFromMaxWallet[to]) {
                require(balanceOf(to) + amount <= maxWalletSize, "Max wallet exceeded");
            }

            uint256 contractTokenBalance = balanceOf(address(this));
            if (contractTokenBalance >= maxTxAmount) {
                contractTokenBalance = maxTxAmount;
            }

            bool overMinTokenBalance = contractTokenBalance >= minLpTokens;
            if (overMinTokenBalance && !inSwapAndLiquify && swapAndLiquifyEnabled && !automatedMarketMakerPairs[from]) {
                swapAndLiquify(contractTokenBalance);
            }
        }

        bool takeFee = true;
        if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
            takeFee = false;
        }

        _tokenTransfer(from, to, amount, takeFee);
    }

    function _tokenTransfer(address sender, address recipient, uint256 amount, bool takeFee) private {
        uint256 taxFee;
        uint256 liquidityFee;
        uint256 marketingFee;
        uint256 burnFee;

        if (takeFee) {
            if (automatedMarketMakerPairs[sender]) {
                taxFee = _taxFeeBuy;
                liquidityFee = _liquidityFeeBuy;
                marketingFee = _marketingFeeBuy;
                burnFee = _burnFeeBuy;
            } else if (automatedMarketMakerPairs[recipient]) {
                taxFee = _taxFeeSell;
                liquidityFee = _liquidityFeeSell;
                marketingFee = _marketingFeeSell;
                burnFee = _burnFeeSell;
            } else {
                taxFee = _taxFeeTransfer;
                liquidityFee = _liquidityFeeTransfer;
                marketingFee = _marketingFeeTransfer;
                burnFee = _burnFeeTransfer;
            }
        }

        _transferStandard(sender, recipient, amount, taxFee, liquidityFee, marketingFee, burnFee);
    }

    function _transferStandard(address sender, address recipient, uint256 tAmount, uint256 taxFee, uint256 liquidityFee, uint256 marketingFee, uint256 burnFee) private {
        uint256 currentRate = _getRate();
        uint256 rAmount = tAmount * currentRate;

        uint256 tTax = tAmount * taxFee / _feeDenominator;
        uint256 rTax = tTax * currentRate;

        uint256 tLiquidity = tAmount * liquidityFee / _feeDenominator;
        uint256 rLiquidity = tLiquidity * currentRate;

        uint256 tMarketing = tAmount * marketingFee / _feeDenominator;
        uint256 rMarketing = tMarketing * currentRate;

        uint256 tBurn = tAmount * burnFee / _feeDenominator;
        uint256 rBurn = tBurn * currentRate;

        uint256 tTransferAmount = tAmount - tTax - tLiquidity - tMarketing - tBurn;
        uint256 rTransferAmount = rAmount - rTax - rLiquidity - rMarketing - rBurn;

        _rOwned[sender] -= rAmount;
        _rOwned[recipient] += rTransferAmount;

        if (_isExcludedFromReward[sender]) {
            _tOwned[sender] -= tAmount;
        }
        if (_isExcludedFromReward[recipient]) {
            _tOwned[recipient] += tTransferAmount;
        }

        _reflectFee(rTax, tTax);
        _rOwned[address(this)] += rLiquidity + rMarketing;
        _tOwned[address(this)] += tLiquidity + tMarketing;

        if (tBurn > 0) {
            _rTotal -= rBurn;
            _tTotal -= tBurn;
            emit Transfer(sender, address(0), tBurn);
        }

        emit Transfer(sender, recipient, tTransferAmount);
    }

    function _reflectFee(uint256 rFee, uint256 tFee) private {
        _rTotal -= rFee;
        _tFeeTotal += tFee;
    }

    function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
        uint256 half = contractTokenBalance / 2;
        uint256 otherHalf = contractTokenBalance - half;
        uint256 initialBalance = address(this).balance;
        swapTokensForEth(half);
        uint256 newBalance = address(this).balance - initialBalance;
        addLiquidity(otherHalf, newBalance);
        emit SwapAndLiquify(half, newBalance, otherHalf);
    }

    function swapTokensForEth(uint256 tokenAmount) private {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();
        _approve(address(this), address(uniswapV2Router), tokenAmount);
        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(tokenAmount, 0, path, address(this), block.timestamp);
    }

    function addLiquidity(uint256 tokenAmount, uint256 ethAmount) private {
        _approve(address(this), address(uniswapV2Router), tokenAmount);
        uniswapV2Router.addLiquidityETH{value: ethAmount}(address(this), tokenAmount, 0, 0, owner(), block.timestamp);
    }

    function isExcludedFromReward(address account) external view returns (bool) {
        return _isExcludedFromReward[account];
    }

    function isExcludedFromFee(address account) external view returns (bool) {
        return _isExcludedFromFee[account];
    }

    function isExcludedFromMaxWallet(address account) external view returns (bool) {
        return _isExcludedFromMaxWallet[account];
    }

    function excludeFromReward(address account) external onlyOwner {
        require(!_isExcludedFromReward[account], "Account already excluded");
        if (_rOwned[account] > 0) {
            _tOwned[account] = tokenFromReflection(_rOwned[account]);
        }
        _isExcludedFromReward[account] = true;
        _excluded.push(account);
    }

    function includeInReward(address account) external onlyOwner {
        require(_isExcludedFromReward[account], "Account not excluded");
        for (uint256 i = 0; i < _excluded.length; i++) {
            if (_excluded[i] == account) {
                _excluded[i] = _excluded[_excluded.length - 1];
                _tOwned[account] = 0;
                _isExcludedFromReward[account] = false;
                _excluded.pop();
                break;
            }
        }
    }

    function excludeFromFee(address account) external onlyOwner {
        _isExcludedFromFee[account] = true;
    }

    function includeInFee(address account) external onlyOwner {
        _isExcludedFromFee[account] = false;
    }

    function excludeFromMaxWallet(address account) external onlyOwner {
        _isExcludedFromMaxWallet[account] = true;
    }

    function includeInMaxWallet(address account) external onlyOwner {
        _isExcludedFromMaxWallet[account] = false;
    }

    function excludeFromMaxTx(address account) external onlyOwner {
        _isExcludedFromMaxTx[account] = true;
    }

    function includeInMaxTx(address account) external onlyOwner {
        _isExcludedFromMaxTx[account] = false;
    }

    function setBuyFees(uint256 taxFee, uint256 liquidityFee, uint256 marketingFee, uint256 burnFee) external onlyOwner {
        require(taxFee + liquidityFee + marketingFee + burnFee <= 30, "Fee above 30% not allowed");
        _taxFeeBuy = taxFee;
        _liquidityFeeBuy = liquidityFee;
        _marketingFeeBuy = marketingFee;
        _burnFeeBuy = burnFee;
    }

    function setSellFees(uint256 taxFee, uint256 liquidityFee, uint256 marketingFee, uint256 burnFee) external onlyOwner {
        require(taxFee + liquidityFee + marketingFee + burnFee <= 30, "Fee above 30% not allowed");
        _taxFeeSell = taxFee;
        _liquidityFeeSell = liquidityFee;
        _marketingFeeSell = marketingFee;
        _burnFeeSell = burnFee;
    }

    function setTransferFees(uint256 taxFee, uint256 liquidityFee, uint256 marketingFee, uint256 burnFee) external onlyOwner {
        _taxFeeTransfer = taxFee;
        _liquidityFeeTransfer = liquidityFee;
        _marketingFeeTransfer = marketingFee;
        _burnFeeTransfer = burnFee;
    }

    function setMaxTx(uint256 maxTx) external onlyOwner {
        require(maxTx >= 1 && maxTx <= 100, "minLpTokens must be between 1 and 100");
        maxTxAmount = _tTotal * maxTx / 100;
    }

    function setMaxWalletSize(uint256 maxWallet) external onlyOwner {
        require(maxWallet >= 1 && maxWallet <= 100, "minLpTokens must be between 1 and 100");
        maxWalletSize = _tTotal * maxWallet / 100;
    }

    function setMinLpTokens(uint256 minTokens) external onlyOwner {
        minLpTokens = minTokens;
    }

    function setMarketingWallet(address wallet) external onlyOwner {
        marketingWallet = wallet;
    }

    function setSwapAndLiquifyEnabled(bool enabled) external onlyOwner {
        swapAndLiquifyEnabled = enabled;
        emit SwapAndLiquifyEnabledUpdated(enabled);
    }

    function allowTrading() external onlyOwner {
        tradingPaused = false;
    }

    function pauseTrading() external onlyOwner {
        tradingPaused = true;
    }

    function canTrade() external view returns (bool) {
        return !tradingPaused;
    }

    function setAMM(address pair, bool value) external onlyOwner {
        automatedMarketMakerPairs[pair] = value;
    }

    function totalFees() external view returns (uint256) {
        return _tFeeTotal;
    }

    function getRTotal() external view returns (uint256) {
        return _rTotal;
    }

    function getTTotal() external view returns (uint256) {
        return _tTotal;
    }

    function getExcludedLength() external view returns (uint256) {
        return _excluded.length;
    }

    function getPreviousMarketingFee() external view returns (uint256) {
        return _previousMarketingFee;
    }

    function getFeeDenominator() external view returns (uint256) {
        return _feeDenominator;
    }

    function getUniswapPair() external view returns (address) {
        return uniswapPair;
    }

    function getMaxTx() external view returns (uint256) {
        return maxTxAmount;
    }

    function getMaxWalletSize() external view returns (uint256) {
        return maxWalletSize;
    }

    function clearStuckBalance(address to) external onlyOwner {
        payable(to).transfer(address(this).balance);
    }

    function claimTokens() external onlyOwner {
        uint256 balance = balanceOf(address(this));
        if (balance > 0) {
            _transfer(address(this), owner(), balance);
        }
    }

    function claimOtherTokens(address token, address to) external onlyOwner {
        IERC20(token).transfer(to, IERC20(token).balanceOf(address(this)));
    }

    function burnWallet() external onlyOwner {
        uint256 balance = balanceOf(address(this));
        require(balance > 0, "No tokens to burn");
        _rTotal -= balance * _getRate();
        _tTotal -= balance;
        emit Transfer(address(this), address(0), balance);
    }

    receive() external payable {}
}
