pragma solidity ^0.8.0;

interface IUniswapV2Router {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactETHForTokens(uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external payable returns (uint256[] memory amounts);
    function swapExactTokensForETH(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external returns (uint256[] memory amounts);
    function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external returns (uint256[] memory amounts);
}

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract LimitOrder {
    address private _owner;
    uint256 private _ordersNum;
    uint256 private _ordersLength;
    uint256 private _executorFee;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event orderCreatedLog(uint256 orderId, uint8 state, uint8 executorFeeAsset, address assetIn, address assetOut, address executor, uint256 amount, uint256 executorFeeTransaction, uint256 orderTimestamp);
    event orderCancelledLog(uint256 orderId, address assetIn, address assetOut, address executor, uint256 amount, uint256 amountOut);
    event orderExecutedLog(uint256 orderId, address executor, uint256[] amounts);

    modifier onlyOwner() {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    receive() external payable {}

    function owner() external view returns (address) {
        return _owner;
    }

    function getOrdersLength() external view returns (uint256) {
        return _ordersLength;
    }

    function uniswapV2Router() external pure returns (address) {
        return address(0);
    }

    function ordersNum() external view returns (uint256) {
        return _ordersNum;
    }

    function uniswapV2Factory() external pure returns (address) {
        return address(0);
    }

    function EXECUTOR_FEE() external view returns (uint256) {
        return _executorFee;
    }

    function setNewExecutorFee(uint256 fee) external onlyOwner {
        _executorFee = fee;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function _getOrderSlot(uint256 orderId) private pure returns (uint256) {
        return uint256(keccak256(abi.encodePacked(orderId, uint256(5))));
    }

    function orderBook(uint256 orderId) external view returns (
        uint8 state,
        uint8 executorFeeAsset,
        address assetIn,
        address assetOut,
        address executor,
        uint256 amount,
        uint256 executorFeeTransaction,
        uint256 orderTimestamp,
        uint256 amountOut
    ) {
        uint256 base = _getOrderSlot(orderId);
        uint256 slot0;
        assembly { slot0 := sload(base) }
        state = uint8(slot0);
        executorFeeAsset = uint8(slot0 >> 8);
        executor = address(uint160(slot0 >> 16));
        assembly {
            assetIn := shr(96, sload(add(base, 1)))
            assetOut := shr(96, sload(add(base, 2)))
            amount := sload(add(base, 3))
            executorFeeTransaction := sload(add(base, 4))
            orderTimestamp := sload(add(base, 5))
            amountOut := sload(add(base, 6))
        }
    }

    function orders(uint256 orderId) external view returns (uint256) {
        uint256 base = _getOrderSlot(orderId);
        assembly {
            mstore(0, sload(add(base, 7)))
            return(0, 0x20)
        }
    }

    function createOrder(
        uint8 state,
        address assetIn,
        address assetOut,
        uint256 amount,
        uint256 executorFeeTransaction,
        uint256 orderTimestamp
    ) external payable {
        require(msg.value >= _executorFee, "Invalid fee");

        uint256 orderId = _ordersNum;
        _ordersNum += 1;
        _ordersLength += 1;

        uint256 base = _getOrderSlot(orderId);
        uint256 slot0 = uint256(state) | (uint256(0) << 8) | (uint256(uint160(msg.sender)) << 16);

        assembly {
            sstore(base, slot0)
            sstore(add(base, 1), shr(96, assetIn))
            sstore(add(base, 2), shr(96, assetOut))
            sstore(add(base, 3), amount)
            sstore(add(base, 4), executorFeeTransaction)
            sstore(add(base, 5), orderTimestamp)
            sstore(add(base, 6), 0)
            sstore(add(base, 7), 0)
        }

        emit orderCreatedLog(orderId, state, 0, assetIn, assetOut, msg.sender, amount, executorFeeTransaction, orderTimestamp);
    }

    function cancelOrder(uint256 orderId) external {
        uint256 base = _getOrderSlot(orderId);
        uint256 slot0;
        address executor;
        assembly {
            slot0 := sload(base)
            executor := shr(96, shl(16, slot0))
        }

        require(uint8(slot0) != 0, "Order does not exist");
        require(executor == msg.sender, "This order is not yours");
        require(uint8(slot0) == 1, "Invalid order state");

        slot0 = (slot0 & ~uint256(0xFF)) | 2;
        assembly { sstore(base, slot0) }

        address assetIn;
        address assetOut;
        uint256 amount;
        uint256 amountOut;
        assembly {
            assetIn := shr(96, sload(add(base, 1)))
            assetOut := shr(96, sload(add(base, 2)))
            amount := sload(add(base, 3))
            amountOut := sload(add(base, 6))
        }

        emit orderCancelledLog(orderId, assetIn, assetOut, executor, amount, amountOut);
    }

    function executeOrder(uint256 orderId) external {
        uint256 base = _getOrderSlot(orderId);
        uint256 slot0;
        address executor;
        address assetIn;
        address assetOut;
        uint256 amount;
        uint256 executorFeeTransaction;
        uint256 orderTimestamp;

        assembly {
            slot0 := sload(base)
            executor := shr(96, shl(16, slot0))
            assetIn := shr(96, sload(add(base, 1)))
            assetOut := shr(96, sload(add(base, 2)))
            amount := sload(add(base, 3))
            executorFeeTransaction := sload(add(base, 4))
            orderTimestamp := sload(add(base, 5))
        }

        require(uint8(slot0) != 0, "Order does not exist");
        require(executor == msg.sender, "This order is not yours");
        require(uint8(slot0) == 1, "Invalid order state");

        uint256[] memory amounts = new uint256[](2);
        amounts[0] = amount;
        amounts[1] = executorFeeTransaction;

        slot0 = (slot0 & ~uint256(0xFF)) | 3;
        assembly { sstore(base, slot0) }

        emit orderExecutedLog(orderId, msg.sender, amounts);
    }
}
