// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

contract TokenVesting {
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event VestingAdded(uint256 indexed id, address indexed beneficiary);
    event VestingCanceled(uint256 indexed id);

    uint256 public constant SECONDS_IN_MONTH = 2592000;
    uint256 public constant ONE_MILLION_TOKENS = 1000000000000000000000000000;
    uint256 public constant PORTION_PER_PERIOD_PRECISION = 10000000000;
    uint256 public constant PORTION_OF_TOTAL_PRECISION = 10000000000;
    uint256 public constant JUNE_1ST_2021_T0000UTC = 1622505600;

    uint256 private _initialized;
    address private _owner;
    address public token;
    uint256 public vestingsCount;
    uint256 private _amountInVestings;
    uint256 public tgeTimestamp;

    modifier onlyOwner() {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function renounceOwnership() public onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function initialize() public {
        require(!isInitialized(), "Initializable: contract is already initialized");
        _initialized |= 0x100;
        _owner = msg.sender;
        token = address(0x725C263e32c72dDC3A19bEa12C5a0479a81eE688);
        tgeTimestamp = JUNE_1ST_2021_T0000UTC;
    }

    function isInitialized() internal view returns (bool) {
        return (_initialized >> 8) & 0xff != 0;
    }

    function getVestingsCount() public view returns (uint256) {
        return vestingsCount;
    }

    function amountInVestings() public view returns (uint256) {
        return _amountInVestings;
    }

    function tgeTimestamp_() public view returns (uint256) {
        return tgeTimestamp;
    }

    function token_() public view returns (address) {
        return token;
    }

    function getTokensAvailable() public view returns (uint256) {
        uint256 bal = IERC20(token).balanceOf(address(this));
        require(bal >= _amountInVestings, "SafeMath: subtraction overflow");
        return bal - _amountInVestings;
    }

    function vestingSchedules(uint8, uint256 index) public view returns (
        address beneficiary,
        uint256 totalAmount,
        uint256 withdrawn,
        uint256 startTime,
        uint256 duration
    ) {
        require(index < vestingsCount, "Index out of bounds");
        (beneficiary, totalAmount, withdrawn, startTime, duration, ) = _getVesting(index);
    }

    function getVestingById(uint256 id) public view returns (
        address beneficiary,
        uint256 totalAmount,
        uint256 withdrawn,
        uint256 startTime,
        uint256 duration,
        bool cancelable
    ) {
        (beneficiary, totalAmount, withdrawn, startTime, duration, cancelable) = _getVesting(id);
    }

    function vestings(uint256 id) public view returns (
        address beneficiary,
        uint256 totalAmount,
        uint256 withdrawn,
        uint256 startTime,
        uint256 duration,
        bool cancelable
    ) {
        return getVestingById(id);
    }

    function _getVesting(uint256 index) internal view returns (
        address beneficiary,
        uint256 totalAmount,
        uint256 withdrawn,
        uint256 startTime,
        uint256 duration,
        bool cancelable
    ) {
        require(index < vestingsCount, "Index out of bounds");
        uint256 base = _vestingSlot(index);
        uint256 slot0;
        assembly { slot0 := sload(base) }
        beneficiary = address(uint160(slot0));
        cancelable = (slot0 >> 160) & 0xff != 0;
        assembly { totalAmount := sload(add(base, 1)) }
        assembly { withdrawn := sload(add(base, 2)) }
        assembly { startTime := sload(add(base, 3)) }
        assembly { duration := sload(add(base, 4)) }
    }

    function _vestingSlot(uint256 index) internal pure returns (uint256) {
        uint256 h1;
        uint256 h2;
        assembly {
            mstore(0x00, index)
            mstore(0x20, 0x69)
            h1 := keccak256(0x00, 0x40)
            mstore(0x00, 0x00)
            mstore(0x20, index)
            h2 := keccak256(0x00, 0x40)
        }
        return h2 * 5 + h1;
    }

    function getWithdrawableAmount(uint256 id) public view returns (uint256) {
        (, uint256 total, uint256 withdrawn, uint256 start, uint256 dur, ) = _getVesting(id);
        if (block.timestamp < start) return 0;
        if (block.timestamp >= start + dur) return total - withdrawn;
        uint256 elapsed = block.timestamp - start;
        uint256 vested = total * elapsed / dur;
        if (vested <= withdrawn) return 0;
        return vested - withdrawn;
    }

    function withdrawFromVesting(uint256 id) public {
        (address beneficiary, uint256 total, uint256 withdrawn, uint256 start, uint256 dur, ) = _getVesting(id);
        require(beneficiary == msg.sender, "Not beneficiary");
        uint256 amount = getWithdrawableAmount(id);
        require(amount > 0, "Nothing to withdraw");
        _updateVestingWithdrawn(id, withdrawn + amount);
        _amountInVestings -= amount;
        IERC20(token).transfer(beneficiary, amount);
    }

    function withdrawFromVestingBulk(uint256 startId, uint256 count) public {
        for (uint256 i = 0; i < count; i++) {
            withdrawFromVesting(startId + i);
        }
    }

    function cancelVesting(uint256 id) public onlyOwner {
        (address beneficiary, uint256 total, uint256 withdrawn, , , bool cancelable) = _getVesting(id);
        require(cancelable, "Vesting is not cancelable");
        uint256 remaining = total - withdrawn;
        _updateVestingWithdrawn(id, total);
        _amountInVestings -= remaining;
        IERC20(token).transfer(_owner, remaining);
        emit VestingCanceled(id);
    }

    function _updateVestingWithdrawn(uint256 id, uint256 newWithdrawn) internal {
        uint256 base = _vestingSlot(id);
        assembly { sstore(add(base, 2), newWithdrawn) }
    }

    function withdrawExcessiveTokens() public onlyOwner {
        uint256 bal = IERC20(token).balanceOf(address(this));
        require(bal >= _amountInVestings, "SafeMath: subtraction overflow");
        uint256 excess = bal - _amountInVestings;
        IERC20(token).transfer(_owner, excess);
    }
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}
