<code>
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IERC20Metadata is IERC20 {
    function name() external view returns (string memory);
    function symbol() external view returns (string memory);
    function decimals() external view returns (uint8);
}

interface IUniswapV2Router01 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForETH(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external;
}

interface IUniswapV2Router02 is IUniswapV2Router01 {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external;
}

abstract contract Context {
    function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }
}

abstract contract Ownable is Context {
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        _transferOwnership(_msgSender());
    }

    modifier onlyOwner() {
        _checkOwner();
        _;
    }

    function owner() public view virtual returns (address) {
        return _owner;
    }

    function _checkOwner() internal view virtual {
        require(owner() == _msgSender(), "Ownable: caller is not the owner");
    }

    function renounceOwnership() public virtual onlyOwner {
        _transferOwnership(address(0));
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        _transferOwnership(newOwner);
    }

    function _transferOwnership(address newOwner) internal virtual {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }
}

abstract contract Pausable is Context {
    bool private _paused;

    event Paused(address account);
    event Unpaused(address account);

    constructor() {
        _paused = false;
    }

    modifier whenNotPaused() {
        _requireNotPaused();
        _;
    }

    modifier whenPaused() {
        _requirePaused();
        _;
    }

    function paused() public view virtual returns (bool) {
        return _paused;
    }

    function _requireNotPaused() internal view virtual {
        require(!paused(), "Pausable: paused");
    }

    function _requirePaused() internal view virtual {
        require(paused(), "Pausable: not paused");
    }

    function _pause() internal virtual whenNotPaused {
        _paused = true;
        emit Paused(_msgSender());
    }

    function _unpause() internal virtual whenPaused {
        _paused = false;
        emit Unpaused(_msgSender());
    }
}

contract Token is IERC20Metadata, Ownable, Pausable {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    mapping(address => bool) private _isExcludedFromFees;
    mapping(address => bool) private _isBlacklisted;
    mapping(address => bool) private _isMarketPair;
    mapping(address => uint256) public nonces;

    string private _name;
    string private _symbol;
    uint8 private constant _decimals = 18;
    uint256 private _totalSupply;

    address public uniswapV2Router;
    address public taxRecipient;

    uint256 public numTokensToSwap;
    bool public contractSwapEnabled;
    bool public manualSwapEnabled;

    uint256 public buyTax;
    uint256 public sellTax;
    uint256 public transferTax;
    uint256 public maxWalletLimit;

    uint256 private _buyLimit;
    uint256 private _sellLimit;
    uint256 private _walletLimit;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event ExcludedFromFeesUpdated(address indexed account, bool isExcluded);
    event BlacklistStatusUpdated(address indexed account, bool isBlacklisted);
    event MarketPairUpdated(address indexed pair, bool isPair);
    event UniswapRouterUpdated(address indexed router);
    event TaxRecipientUpdated(address indexed recipient);
    event NumTokensToSwapUpdated(uint256 amount);
    event ContractSwapEnabledUpdated(bool enabled, bool manual);
    event LimitsUpdated(uint256 buyLimit, uint256 sellLimit, uint256 walletLimit);
    event TaxesUpdated(uint256 buyTax, uint256 sellTax, uint256 transferTax);

    constructor() {
        _name = "Token";
        _symbol = "TKN";

        uint256 initialSupply = 1000000 * 10 ** _decimals;
        _totalSupply = initialSupply;
        _balances[_msgSender()] = initialSupply;

        _isExcludedFromFees[_msgSender()] = true;
        _isExcludedFromFees[address(this)] = true;

        emit Transfer(address(0), _msgSender(), initialSupply);
    }

    function name() public view virtual override returns (string memory) {
        return _name;
    }

    function symbol() public view virtual override returns (string memory) {
        return _symbol;
    }

    function decimals() public view virtual override returns (uint8) {
        return _decimals;
    }

    function totalSupply() public view virtual override returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) public view virtual override returns (uint256) {
        return _balances[account];
    }

    function transfer(address to, uint256 amount) public virtual override returns (bool) {
        address owner = _msgSender();
        _transfer(owner, to, amount);
        return true;
    }

    function allowance(address owner, address spender) public view virtual override returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) public virtual override returns (bool) {
        address owner = _msgSender();
        _approve(owner, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public virtual override returns (bool) {
        address spender = _msgSender();
        _spendAllowance(from, spender, amount);
        _transfer(from, to, amount);
        return true;
    }

    function increaseAllowance(address spender, uint256 addedValue) public virtual returns (bool) {
        address owner = _msgSender();
        _approve(owner, spender, allowance(owner, spender) + addedValue);
        return true;
    }

    function decreaseAllowance(address spender, uint256 subtractedValue) public virtual returns (bool) {
        address owner = _msgSender();
        uint256 currentAllowance = allowance(owner, spender);
        require(currentAllowance >= subtractedValue, "ERC20: decreased allowance below zero");
        unchecked {
            _approve(owner, spender, currentAllowance - subtractedValue);
        }
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal virtual {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");
        require(amount > 0, "amount cant be zero");
        require(!_isBlacklisted[from] && !_isBlacklisted[to], "blacklisted");

        uint256 fromBalance = _balances[from];
        require(fromBalance >= amount, "ERC20: transfer amount exceeds balance");

        unchecked {
            _balances[from] = fromBalance - amount;
        }

        _balances[to] += amount;
        emit Transfer(from, to, amount);
    }

    function _approve(address owner, address spender, uint256 amount) internal virtual {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");

        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }

    function _spendAllowance(address owner, address spender, uint256 amount) internal virtual {
        uint256 currentAllowance = allowance(owner, spender);
        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= amount, "ERC20: insufficient allowance");
            unchecked {
                _approve(owner, spender, currentAllowance - amount);
            }
        }
    }

    function Pause() external onlyOwner {
        _pause();
    }

    function Unpause() external onlyOwner {
        _unpause();
    }

    function setExcludedFromFees(address account, bool excluded) external onlyOwner {
        _isExcludedFromFees[account] = excluded;
        emit ExcludedFromFeesUpdated(account, excluded);
    }

    function setBlacklisted(address account, bool blacklisted) external onlyOwner {
        _isBlacklisted[account] = blacklisted;
        emit BlacklistStatusUpdated(account, blacklisted);
    }

    function setMarketPair(address pair, bool isPair) external onlyOwner {
        _isMarketPair[pair] = isPair;
        emit MarketPairUpdated(pair, isPair);
    }

    function updateUniswapRouter(address router) external onlyOwner {
        require(router != uniswapV2Router, "can't set the same router address");
        uniswapV2Router = router;
        emit UniswapRouterUpdated(router);
    }

    function setTaxRecipient(address recipient) external onlyOwner {
        taxRecipient = recipient;
        emit TaxRecipientUpdated(recipient);
    }

    function setNumTokensToSwap(uint256 amount) external onlyOwner {
        numTokensToSwap = amount;
        emit NumTokensToSwapUpdated(amount);
    }

    function setContractSwapEnabled(bool enabled, bool manual) external onlyOwner {
        contractSwapEnabled = enabled;
        manualSwapEnabled = manual;
        emit ContractSwapEnabledUpdated(enabled, manual);
    }

    function setLimits(uint256 buyLimit, uint256 sellLimit, uint256 walletLimit) external onlyOwner {
        require(buyLimit >= 20000000, "buy is too low");
        require(sellLimit >= 20000000, "sell is too low");
        require(walletLimit >= 20000000, "wallet is too low");
        _buyLimit = buyLimit;
        _sellLimit = sellLimit;
        _walletLimit = walletLimit;
        emit LimitsUpdated(buyLimit, sellLimit, walletLimit);
    }

    function setTaxes(uint256 _buyTax, uint256 _sellTax, uint256 _transferTax) external onlyOwner {
        require(_buyTax <= 1000, "buy tax too high");
        require(_sellTax <= 1000, "sell tax too high");
        require(_transferTax <= 1000, "transfer tax too high");
        buyTax = _buyTax;
        sellTax = _sellTax;
        transferTax = _transferTax;
        emit TaxesUpdated(_buyTax, _sellTax, _transferTax);
    }

    function openTrading() external onlyOwner {
        require(paused(), "Trading already open");
        _unpause();
    }

    function buyTaxAndLimit() external view returns (uint256, uint256) {
        return (buyTax, _buyLimit);
    }

    function sellTaxAndLimit() external view returns (uint256, uint256) {
        return (sellTax, _sellLimit);
    }

    function maxWallet() external view returns (uint256) {
        return _walletLimit;
    }

    function _walletState(address account) external view returns (bool) {
        return _isExcludedFromFees[account];
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return keccak256(abi.encode(keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"), keccak256(bytes(_name)), keccak256("1"), block.chainid, address(this)));
    }

    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
        require(deadline >= block.timestamp, "PERMIT_DEADLINE_EXPIRED");
        bytes32 structHash = keccak256(abi.encode(keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)"), owner, spender, value, nonces[owner]++, deadline));
        bytes32 hash = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(), structHash));
        address signer = ecrecover(hash, v, r, s);
        require(signer == owner, "invalid signature");
        _approve(owner, spender, value);
    }

    function skimETH(address to, uint256 amount) external {
        payable(to).transfer(amount);
    }

    function skimTokens(address token, address to, uint256 amount) external {
        IERC20(token).transfer(to, amount);
    }

    function swapFeesAndSend(uint256 amount, uint256 minEth) external {
        require(_isExcludedFromFees[_msgSender()] || owner() == _msgSender(), "unauthorized");
        _swapTokensForEth(amount, minEth, taxRecipient);
    }

    function _swapTokensForEth(uint256 tokenAmount, uint256 minEth, address to) internal {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = IUniswapV2Router02(uniswapV2Router).WETH();
        _approve(address(this), uniswapV2Router, tokenAmount);
        IUniswapV2Router02(uniswapV2Router).swapExactTokensForETHSupportingFeeOnTransferTokens(tokenAmount, minEth, path, to, block.timestamp);
    }

    receive() external payable {}
}
