    function setMinPurchase(uint256 _min, uint256 _minUSDT) external onlyOwner {
        minPurchase = _min;
        minPurchaseUSDT = _minUSDT;
        emit UpdateMinPurchase(_min, _minUSDT, _min, _minUSDT);
    }

    function minmumPurchaseInUSDT() external view returns (uint256) {
        return minPurchaseUSDT;
    }

    function BSCbuyers(address[] calldata _buyers, uint256[] calldata _amounts) external onlyOwner {
        require(_buyers.length == _amounts.length, "Invalid data length");
        for (uint256 i = 0; i < _buyers.length; i++) {
            users[_buyers[i]] += _amounts[i];
        }
    }

    function oldBuyer(address _buyer) external view returns (bool) {
        return users[_buyer] > 0;
    }

    function minmumPurchaseInNative() external view returns (uint256) {
        return minPurchase;
    }

    function getLatestPrice() public view returns (uint256) {
        (, int256 price, , , ) = AggregatorV3Interface(HPO).latestRoundData();
        return uint256(price);
    }

    function tokenPerUsd() external view returns (uint256) {
        return divider;
    }

    function changePrice(uint256 _price) external onlyOwner {
        uint256 oldPrice = divider;
        divider = _price;
        emit UpdatePrice(oldPrice, _price);
    }

    function changeOwner(address _newOwner) external onlyOwner {
        require(_newOwner != address(0), "Ownable: new owner is the zero address");
        address oldOwner = owner;
        owner = _newOwner;
        emit OwnershipTransferred(oldOwner, _newOwner);
    }

    function userInfo(address _user) external view returns (uint256, uint256, uint256, uint256) {
        return (users[_user], wallets[_user], 0, 0);
    }

    function _getPresaleStatus() internal view returns (bool) {
        return _presaleStatus;
    }

    function _setPresaleStatus(bool _status) internal {
        _presaleStatus = _status;
    }

    function buyTokenUSDT(address _wallet, uint256 _amount) external {
        require(_getPresaleStatus(), "Presale : Presale is not finished");
        require(_amount >= minPurchaseUSDT, "Presale : amount must be greater than minimum purchase");
        require(amountRaisedUSDT < SupplyPerPhase, "All Sold");
        uint256 tokenAmount = usdtToToken(_amount);
        soldToken += _amount;
        amountRaisedUSDT += _amount;
        users[msg.sender] += tokenAmount;
        wallets[_wallet] += tokenAmount;
    }

    function transferTokens(address _token, uint256 _amount) external onlyOwner {
        (bool success, ) = _token.call(abi.encodeWithSelector(IERC20.transfer.selector, fundReceiver, _amount));
        require(success, "Token transfer failed");
    }

    receive() external payable {}
}
